import com.google.protos.youtube.api.innertube.BrowseEndpointOuterClass;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import android.app.*;import android.view.*;import android.widget.*;import java.lang.ref.*;import java.lang.reflect.*;import ultra.downloads.NativeLibrarySelection;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class NativeSelectionUiTest {
 Activity a;FrameLayout root;LinearLayout list;Method bind;
 @Before public void setup()throws Exception{a=Robolectric.buildActivity(Activity.class).setup().get();a.setTheme(android.R.style.Theme_Material_NoActionBar);root=new FrameLayout(a);list=new LinearLayout(a);list.setOrientation(1);root.addView(list);a.setContentView(root);NativeLibrarySelection.unbind();set("currentRoot",new WeakReference<View>(root));set("currentRecycler",new WeakReference<ViewGroup>(list));bind=NativeLibrarySelection.class.getDeclaredMethod("bindViewWithModel",View.class,Object.class);bind.setAccessible(true);}
 void set(String name,Object value)throws Exception{Field f=NativeLibrarySelection.class.getDeclaredField(name);f.setAccessible(true);f.set(null,value);}
 bqtu model(String id){bizw ep=(bizw)bizw.a.createBuilder().instance;ep.c=id;bhbf b=(bhbf)bjue.a.createBuilder();b.e(BrowseEndpointOuterClass.browseEndpoint,ep);bqtu row=(bqtu)bqtu.a.createBuilder().instance;row.i=(bjue)b.build();return row;}
 FrameLayout row(String id,int[] taps)throws Exception{FrameLayout row=new FrameLayout(a);Button nativeButton=new Button(a);nativeButton.setOnClickListener(v->taps[0]++);row.addView(nativeButton);list.addView(row,new LinearLayout.LayoutParams(-1,72));bind.invoke(null,row,model(id));return row;}
 @Test public void longPressChildSelectsAndOverlayTogglesWithoutNativePlayback()throws Exception{int[] taps={0};FrameLayout one=row("VLPLone",taps),two=row("VLPLtwo",taps);one.getChildAt(0).performClick();assertEquals(1,taps[0]);assertTrue(one.getChildAt(0).performLongClick());assertEquals(1,NativeLibrarySelection.count());View overlay=two.findViewWithTag("native_lib_selection_touch");assertNotNull(overlay);overlay.performClick();assertEquals(2,NativeLibrarySelection.count());assertEquals(1,taps[0]);assertTrue(((CheckBox)two.findViewWithTag("native_lib_cb")).isChecked());NativeLibrarySelection.exit();assertEquals(View.GONE,overlay.getVisibility());one.getChildAt(0).performClick();assertEquals(2,taps[0]);}
 @Test public void recycleToUnknownHidesSelectionAndClearsIdentity()throws Exception{FrameLayout row=row("VLPLone",new int[]{0});row.getChildAt(0).performLongClick();bind.invoke(null,row,null);assertNull(row.getTag(0x7e020002));assertEquals(View.GONE,row.findViewWithTag("native_lib_selection_touch").getVisibility());}
 @Test public void plainTextAndArtworkLongPressSelectWithoutPlaying()throws Exception{int[] taps={0};FrameLayout r=row("VLPLone",taps);TextView title=new TextView(a);title.setText("Title");r.addView(title);bind.invoke(null,r,model("VLPLone"));assertFalse("text must not swallow native row tap",title.isLongClickable());assertTrue(r.performLongClick());assertEquals(1,NativeLibrarySelection.count());assertEquals(0,taps[0]);}
 @Test public void likedMusicIdentityCanBeSelected()throws Exception{FrameLayout r=row("LM",new int[]{0});assertTrue(r.getChildAt(0).performLongClick());assertEquals(1,NativeLibrarySelection.count());}
 @Test public void overlaySwipeScrollsNativeListAndNeverToggles()throws Exception{FrameLayout r=row("VLPLone",new int[]{0});r.getChildAt(0).performLongClick();final java.util.ArrayList<Integer> events=new java.util.ArrayList<>();LinearLayout tracking=new LinearLayout(a){public void scrollBy(int x,int y){assertEquals(0,x);events.add(y);}};set("currentRecycler",new WeakReference<ViewGroup>(tracking));View o=r.findViewWithTag("native_lib_selection_touch");long now=android.os.SystemClock.uptimeMillis();for(int[] p:new int[][]{{0,600},{2,400},{2,200},{1,100}}){MotionEvent e=MotionEvent.obtain(now,now+events.size()*40,p[0],40,p[1],0);o.dispatchTouchEvent(e);e.recycle();}assertEquals(java.util.Arrays.asList(200,200),events);assertEquals(1,NativeLibrarySelection.count());}
 @Test public void overlayTapTogglesAndCancelDoesNot()throws Exception{FrameLayout r=row("VLPLone",new int[]{0});r.getChildAt(0).performLongClick();View o=r.findViewWithTag("native_lib_selection_touch");long now=android.os.SystemClock.uptimeMillis();for(int act:new int[]{0,3}){MotionEvent e=MotionEvent.obtain(now,now+30,act,40,40,0);o.dispatchTouchEvent(e);e.recycle();}assertEquals(1,NativeLibrarySelection.count());for(int act:new int[]{0,1}){MotionEvent e=MotionEvent.obtain(now,now+30,act,40,40,0);o.dispatchTouchEvent(e);e.recycle();}assertEquals(0,NativeLibrarySelection.count());}
 @Test public void gestureUsesActualScrollableAncestorRatherThanStalePageList()throws Exception{final int[] dy={0};FrameLayout ancestor=new FrameLayout(a){public boolean canScrollVertically(int direction){return true;}public void scrollBy(int x,int y){dy[0]+=y;}};FrameLayout r=row("VLPLone",new int[]{0});list.removeView(r);ancestor.addView(r);list.addView(ancestor);set("currentRecycler",new WeakReference<ViewGroup>(ancestor));r.getChildAt(0).performLongClick();set("currentRecycler",new WeakReference<ViewGroup>(list));View o=r.findViewWithTag("native_lib_selection_touch");long now=android.os.SystemClock.uptimeMillis();for(int[] p:new int[][]{{0,600},{2,400},{1,400}}){MotionEvent e=MotionEvent.obtain(now,now+30,p[0],40,p[1],0);o.dispatchTouchEvent(e);e.recycle();}assertEquals(200,dy[0]);assertEquals(1,NativeLibrarySelection.count());}
 @Test public void overlayDoesNotBlockNativeParentDragInterception()throws Exception{final boolean[] blocked={false};FrameLayout parent=new FrameLayout(a){public void requestDisallowInterceptTouchEvent(boolean disallow){blocked[0]|=disallow;super.requestDisallowInterceptTouchEvent(disallow);}};FrameLayout r=row("VLPLone",new int[]{0});list.removeView(r);parent.addView(r);list.addView(parent);set("currentRecycler",new WeakReference<ViewGroup>(parent));r.getChildAt(0).performLongClick();View o=r.findViewWithTag("native_lib_selection_touch");long now=android.os.SystemClock.uptimeMillis();for(int action:new int[]{0,3}){MotionEvent e=MotionEvent.obtain(now,now+30,action,40,40,0);o.dispatchTouchEvent(e);e.recycle();}assertFalse(blocked[0]);assertEquals(1,NativeLibrarySelection.count());}
 @Test public void passiveChildrenCannotSwallowNativePlaylistTap()throws Exception{int[] taps={0};FrameLayout r=new FrameLayout(a);r.setOnClickListener(v->taps[0]++);TextView title=new TextView(a);r.addView(title);list.addView(r);bind.invoke(null,r,model("VLPLone"));assertFalse(title.isClickable());assertFalse(title.isLongClickable());r.performClick();assertEquals(1,taps[0]);assertFalse(NativeLibrarySelection.isActive());assertTrue(r.performLongClick());assertEquals(1,NativeLibrarySelection.count());NativeLibrarySelection.exit();r.performClick();assertEquals(2,taps[0]);}
 @After public void cleanup(){NativeLibrarySelection.unbind();}
}
